-- =============================================================================
-- database/seed.sql — Dữ liệu mẫu cho WebArchive (đề tài 16)
-- ----------------------------------------------------------------------------
-- Nội dung được port từ src/sample_data.php (giao diện UI phase) sang bảng
-- MySQL. Hash mật khẩu là bcrypt thật (password_hash / PASSWORD_DEFAULT).
-- Tài khoản demo:
--   user@demo.vn  / demo123   (Người dùng — Lê Minh Tuấn)
--   admin@demo.vn / admin123  (Quản trị viên — Trần Hoàng Nam)
-- Tệp này được áp dụng bởi scripts/setup_db.php sau khi áp dụng schema.sql.
-- =============================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- users — tài khoản (demo + các tài khoản mẫu của bảng quản trị)

-- libraries — 3 thư viện chuyên đề

-- library_members — thành viên & vai trò (owner / editor / viewer)

-- tags — 12 nhãn phân loại

-- saved_pages — 8 URL đã lưu

-- snapshots — mỗi bài viết có đúng một phiên bản snapshot đã lưu

-- assets — tài nguyên cục bộ của từng phiên bản snapshot

-- page_tags — liên kết thẻ với các trang đã lưu

-- allowlist_domains — danh sách tên miền được duyệt để lưu trang

SET FOREIGN_KEY_CHECKS = 1;
